static Sprite ReferenceSprite(string path){foreach(var asset in AssetDatabase.LoadAllAssetsAtPath(path))if(asset is Sprite sprite)return sprite;throw new System.InvalidOperationException($"Sprite import failed: {path}");}
static void PrepareCityBackground(){const string path="Assets/Reference/citybackground.png";var importer=AssetImporter.GetAtPath(path)as TextureImporter;if(importer==null)throw new System.InvalidOperationException("citybackground.png TextureImporter was not found.");importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.spritePixelsPerUnit=240;importer.spritePivot=new Vector2(.5f,.5f);importer.mipmapEnabled=false;importer.filterMode=FilterMode.Point;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.maxTextureSize=4096;importer.SaveAndReimport();}
static void EnsureFolders(){foreach(var p in new[]{"Assets/Data","Assets/Prefabs","Assets/Scenes"})if(!AssetDatabase.IsValidFolder(p))AssetDatabase.CreateFolder("Assets",p.Substring(7));}static T Asset<T>(string path)where T:ScriptableObject{var a=AssetDatabase.LoadAssetAtPath<T>(path);if(a!=null)return a;a=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(a,path);return a;}static Sprite MakeSprite(){const string path="Assets/Data/PlaceholderSprite.asset";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);if(s!=null)return s;var t=new Texture2D(1,1);t.SetPixel(0,0,Color.white);t.Apply();t.name="PlaceholderTexture";AssetDatabase.CreateAsset(t,"Assets/Data/PlaceholderTexture.asset");s=Sprite.Create(t,new Rect(0,0,1,1),new Vector2(.5f,.5f),1);s.name="PlaceholderSprite";AssetDatabase.AddObjectToAsset(s,t);AssetDatabase.SaveAssets();return s;}static T CreatePrefab<T>(string name,Sprite s,Color c,string path,Vector3 scale)where T:Component{var go=SpriteObject(name,s,c,null,Vector3.zero,scale);go.AddComponent<T>();var result=PrefabUtility.SaveAsPrefabAsset(go,path).GetComponent<T>();Object.DestroyImmediate(go);return result;}static T CreateTextPrefab<T>(string name,string path,int size)where T:Component{var go=new GameObject(name,typeof(RectTransform),typeof(Text),typeof(T));var text=go.GetComponent<Text>();text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.fontSize=size;text.alignment=TextAnchor.MiddleCenter;text.color=Color.white;var result=PrefabUtility.SaveAsPrefabAsset(go,path).GetComponent<T>();Object.DestroyImmediate(go);return result;}static void CreateBackgroundPrefab(Sprite s){var go=BackgroundObject("Repeating Background",s,null,Vector3.zero);PrefabUtility.SaveAsPrefabAsset(go,"Assets/Prefabs/RepeatingBackground.prefab");Object.DestroyImmediate(go);}static GameObject BackgroundObject(string n,Sprite s,Transform p,Vector3 pos){var go=SpriteObject(n,s,Color.white,p,pos,Vector3.one);go.GetComponent<SpriteRenderer>().sortingOrder=-100;return go;}static GameObject SpriteObject(string n,Sprite s,Color c,Transform p,Vector3 pos,Vector3 scale){var go=new GameObject(n,typeof(SpriteRenderer));go.transform.SetParent(p);go.transform.position=pos;go.transform.localScale=scale;var r=go.GetComponent<SpriteRenderer>();r.sprite=s;r.color=c;return go;}static GameObject Child(GameObject p,string n){var go=new GameObject(n);go.transform.SetParent(p.transform);return go;}static Text Label(Transform p,string value,Vector2 pos,TextAnchor anchor,int size){var go=new GameObject(value,typeof(RectTransform),typeof(Text));go.transform.SetParent(p,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=Anchor(anchor);r.pivot=Anchor(anchor);r.anchoredPosition=pos;r.sizeDelta=new Vector2(240,40);var t=go.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=value;t.fontSize=size;t.alignment=anchor;t.color=Color.white;return t;}static Vector2 Anchor(TextAnchor a)=>a switch{TextAnchor.UpperLeft=>new Vector2(0,1),TextAnchor.UpperRight=>new Vector2(1,1),TextAnchor.LowerLeft=>Vector2.zero,_=>new Vector2(.5f,.5f)};static void Set(Object o,string field,Object value){var so=new SerializedObject(o);so.FindProperty(field).objectReferenceValue=value;so.ApplyModifiedPropertiesWithoutUndo();}
